11	  <meta name="apple-mobile-web-app-capable" content="yes">
12	  <meta property="og:title" content="Interactive Circle - Color Demo">
13	  <meta property="og:description" content="An interactive color-changing circle with smooth animations, keyboard shortcuts, and touch support.">
14	  <meta property="og:type" content="website">
15	  <meta property="og:image" content="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 400 400'%3E%3Ccircle cx='200' cy='200' r='200' fill='%23ffd700'/%3E%3C/svg%3E">
16	  <meta name="twitter:card" content="summary">
