556	<body>
557	  <button type="button" class="help-btn" id="help-btn" aria-label="Show keyboard shortcuts" title="Help (press ?)">?</button>
558	
559	  <div class="modal" id="help-modal" role="dialog" aria-labelledby="modal-header" aria-modal="true">
560	    <div class="modal-content">
561	      <button type="button" class="modal-close" id="modal-close" aria-label="Close help">✕</button>
562	      <div class="modal-header" id="modal-header">Keyboard Shortcuts</div>
563	      <div class="modal-shortcuts">
564	        <div class="shortcut-item">
565	          <span class="shortcut-key">C</span>
566	          <span class="shortcut-desc">Cycle to next color</span>
567	        </div>
568	        <div class="shortcut-item">
569	          <span class="shortcut-key">R</span>
570	          <span class="shortcut-desc">Reset to default</span>
571	        </div>
572	        <div class="shortcut-item">
573	          <span class="shortcut-key">Space</span>
574	          <span class="shortcut-desc">Toggle active state</span>
575	        </div>
576	        <div class="shortcut-item">
577	          <span class="shortcut-key">↩</span>
578	          <span class="shortcut-desc">Toggle active state</span>
579	        </div>
580	        <div class="shortcut-item">
581	          <span class="shortcut-key">Esc</span>
582	          <span class="shortcut-desc">Reset to default</span>
583	        </div>
584	        <div class="shortcut-item">
585	          <span class="shortcut-key">?</span>
586	          <span class="shortcut-desc">Show this help</span>
587	        </div>
588	      </div>
589	    </div>
590	  </div>
591	
