  colorShiftDuration: 500,
  saveDebounceDuration: 100,
  keyDebounce: 50,
  isTouch: (() => {
    return ('ontouchstart' in window) ||
           (navigator.maxTouchPoints > 0) ||
           (navigator.msMaxTouchPoints > 0) ||
           (window.matchMedia?.('(pointer:coarse)').matches || false);
  })()
};

const el = {
  circle: document.getElementById('decorative-circle'),
  hint: document.getElementById('hint-text'),
  modeIndicator: document.getElementById('mode-indicator'),
  cycleBtn: document.getElementById('cycle-btn'),
  resetBtn: document.getElementById('reset-btn'),
  helpBtn: document.getElementById('help-btn'),
  helpModal: document.getElementById('help-modal'),
  modalClose: document.getElementById('modal-close')
};

let state = { active: false, colorMode: 0 };
let tapCount = 0;
let tapTimeout = null;
let animatingColorShift = false;
let saveTimeout = null;
let lastKeyTime = 0;

const haptic = {
  light: () => {
    try {
      navigator.vibrate?.(10);
    } catch (e) {
      // Silently fail if vibration not available
    }
  },
  medium: () => {
    try {
      navigator.vibrate?.(20);
    } catch (e) {
      // Silently fail if vibration not available
    }
  },
  pattern: (arr) => {
    try {
      navigator.vibrate?.(arr);
    } catch (e) {
      // Silently fail if vibration not available
    }
